INSERT INTO `mensajes_chat` (`id`, `emisor_id`, `receptor_id`, `negocio_id`, `mensaje`, `leido`, `fecha_envio`) VALUES
(1, 7, 1, 32, 'Buenas tardes maestro, ¿tienen disponibilidad para revisar una fuga de agua en una tubería principal en el barrio El Triunfo?', 1, '2026-09-01 09:15:00'),
(2, 1, 7, 32, '¡Hola muy buenos días! Claro que sí con mucho gusto, estamos disponibles. ¿Es en casa o finca?', 1, '2026-09-01 09:18:00'),
(3, 7, 1, 32, 'Es en una casa cerca al parque principal. ¿Cuánto cuesta la visita técnica?', 1, '2026-09-01 09:20:00'),
(4, 1, 7, 32, 'La revisión y diagnóstico tiene un costo de $25.000 COP. Si realizamos el arreglo, se descuenta del valor total del trabajo.', 1, '2026-09-01 09:22:00'),
(5, 7, 1, 32, 'Perfecto, me parece muy bien. ¿Podría pasar hoy a las 2:00 PM?', 1, '2026-09-01 09:25:00'),
(6, 1, 7, 32, 'Listo confirmado. A las 2:00 PM estaré allá con las herramientas y repuestos necesarios.', 1, '2026-09-01 09:28:00'),
(7, 7, 1, 1, 'Hola Doña Stella, ¿tienen quesillos frescos en hoja de plátano para envío hoy?', 1, '2026-09-01 10:10:00'),
(8, 1, 7, 1, '¡Hola! Sí señor, hoy sacamos quesillo fresco de 500g y 1kg recién cuajado, y también achiras tradicionales recién horneadas.', 1, '2026-09-01 10:12:00'),
(9, 7, 1, 1, 'Excelente, me gustaría pedir 3 quesillos de 500g ($45.000) y un paquete de achiras ($10.000). Total $55.000 COP.', 1, '2026-09-01 10:15:00'),
(10, 1, 7, 1, '¡Con gusto! Ya mismo te empaco el pedido y te lo enviamos con el domiciliario.', 1, '2026-09-01 10:18:00'),
(11, 7, 1, 2, 'Buenas tardes, ¿tienen mesa disponible para 4 personas este domingo y mojarra frita grande?', 1, '2026-08-31 16:30:00'),
(12, 1, 7, 2, '¡Buenas tardes! Sí señor, tenemos kioscos frente al embalse y mojarra roja fresca de 1.5 lb y 2 lb garantizada.', 1, '2026-08-31 16:35:00'),
(13, 7, 1, 2, 'Excelente, nos vemos el domingo a la 1:00 PM. Muchas gracias.', 1, '2026-08-31 16:40:00');
INSERT INTO `negocios` (`id`, `usuario_id`, `categoria_id`, `sector_id`, `nombre`, `slug`, `descripcion`, `direccion`, `telefono`, `whatsapp`, `email`, `sitio_web`, `facebook`, `instagram`, `latitud`, `longitud`, `logo`, `imagen_portada`, `estado`, `verificado`, `destacado`, `visitas`, `fecha_creacion`, `fecha_actualizacion`) VALUES
(1, 1, 1, 1, 'Quesillos y Tradición Yaguareña Doña Stella', 'quesillos-y-tradici-on-yaguare-na-do-na-stella-1', 'Más de 30 años elaborando el auténtico quesillo yaguareño envuelto en hoja de plátano con leche pura.', 'Carrera 4 # 5-20, Centro', 3124567890, 3124567890, NULL, NULL, NULL, NULL, 2.66300000, -75.52100000, 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?w=200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1486297678162-eb2a19b0a32d?w=1000&auto=format&fit=crop&q=80', 'activo', 1, 0, 344, '2026-09-01 10:03:36', '2026-09-01 10:26:49'),
(2, 1, 1, 2, 'Pescadería & Estadero El Malecón de Betania', 'pescader-ia-estadero-el-malec-on-de-betania-2', 'Pescado fresco del Embalse de Betania. Especialistas en Mojarra Roja Frita crocante y Viudo de Capaz.', 'Malecón Turístico Embalse de Betania', 3157891234, 3157891234, NULL, NULL, NULL, NULL, 2.66300000, -75.52100000, 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1534422298391-e4f8c172dddb?w=1000&auto=format&fit=crop&q=80', 'activo', 1, 0, 604, '2026-09-01 10:03:36', '2026-09-01 10:26:49'),
(3, 1, 1, 3, 'Asados & Tradición Huilense Don Pedro', 'asados-tradici-on-huilense-don-pedro-3', 'Auténtico asado huilense horneado en tiesto de barro con insulso, arepa de choclo y tamales.', 'Calle 8 # 3-15, Las Ferias', 3109876543, 3109876543, NULL, NULL, NULL, NULL, 2.66300000, -75.52100000, 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544025162-d76694265947?w=1000&auto=format&fit=crop&q=80', 'activo', 1, 1, 649, '2026-09-01 10:03:36', '2026-09-01 10:29:24'),
(4, 1, 1, 7, 'Estadero & Restaurante Campestre Brisas de Betania', 'estadero-restaurante-campestre-brisas-de-betania-4', 'Restaurante típico con kioscos a orillas del embalse. Sancocho de gallina criolla campesina y trucha.', 'Sector La Playa Embalse de Betania', 3189012345, 3189012345, NULL, NULL, NULL, NULL, 2.66300000, -75.52100000, 'https://images.unsplash.com/photo-1556157382-97eda2d62296?w=200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1543353071-873f17a7a088?w=1000&auto=format&fit=crop&q=80', 'activo', 1, 0, 615, '2026-09-01 10:03:36', '2026-09-01 10:26:49'),
(5, 1, 1, 1, 'Fábrica de Quesillos & Lácteos Don Ramiro', 'f-abrica-de-quesillos-l-acteos-don-ramiro-5', 'Elaboración de quesillo huilense en bloque y al detal, doble crema y cuajadas frescas de ordeño.', 'Carrera 3 # 6-30, Centro', 3123456780, 3123456780, NULL, NULL, NULL, NULL, 2.66300000, -75.52100000, 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1550583724-b2692b85b150?w=1000&auto=format&fit=crop&q=80', 'activo', 1, 0, 600, '2026-09-01 10:03:36', '2026-09-01 10:26:49'),
(6, 1, 2, 1, 'Bizcochería & Achiras La Yaguareñita', 'bizcocher-ia-achiras-la-yaguare-nita-6', 'Las mejores Achiras de Yaguará horneadas con leña y cuajada pura campesina. Bizcochos de manteca.', 'Carrera 5 # 4-10, Centro', 3112345678, 3112345678, NULL, NULL, NULL, NULL, 2.66300000, -75.52100000, 'https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?w=200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1509440159596-0249088772ff?w=1000&auto=format&fit=crop&q=80', 'activo', 1, 1, 407, '2026-09-01 10:03:36', '2026-09-01 10:26:49'),
(7, 1, 2, 1, 'Panadería y Cafetería El Parque Yaguará', 'panader-ia-y-cafeter-ia-el-parque-yaguar-a-7', 'Pan aliñado caliente a las 6am y 4pm, pandebonos, buñuelos, empanadas y desayunos.', 'Esquina Parque Principal', 3145678901, 3145678901, NULL, NULL, NULL, NULL, 2.66300000, -75.52100000, 'https://images.unsplash.com/photo-1519085360753-af0119f7cbe7?w=200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1555507036-ab1f4038808a?w=1000&auto=format&fit=crop&q=80', 'activo', 1, 0, 708, '2026-09-01 10:03:36', '2026-09-01 10:26:49'),
(8, 1, 2, 4, 'Panadería y Pastelería La Espiga Dorada Yaguará', 'panader-ia-y-pasteler-ia-la-espiga-dorada-yaguar-a-8', 'Tortas para cumpleaños personalizadas, brazo de reina, postres de tres leches y galletas.', 'Calle 10 # 6-40, Barrio Upar', 3165678901, 3165678901, NULL, NULL, NULL, NULL, 2.66300000, -75.52100000, 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1578985545062-69928b1d9587?w=1000&auto=format&fit=crop&q=80', 'activo', 1, 0, 780, '2026-09-01 10:03:36', '2026-09-01 10:26:49'),
(9, 1, 2, 1, 'Bizcochería Tradición Huilense Doña Flor', 'bizcocher-ia-tradici-on-huilense-do-na-flor-9', 'Elaboración tradicional de cucas, bizcochuelos, panderitos y colaciones típicas.', 'Carrera 6 # 3-12, Centro', 3158901234, 3158901234, NULL, NULL, NULL, NULL, 2.66300000, -75.52100000, 'https://images.unsplash.com/photo-1580489944761-15a19d654956?w=200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1589367920969-ab8e050bbb04?w=1000&auto=format&fit=crop&q=80', 'activo', 1, 1, 294, '2026-09-01 10:03:36', '2026-09-01 10:26:49'),
(10, 1, 3, 5, 'Supertienda y Abarrotes El Triunfo de Yaguará', 'supertienda-y-abarrotes-el-triunfo-de-yaguar-a-10', 'Todo para el mercado del hogar: víveres, arroz de Campoalegre, panela, aceite y huevos campesinos.', 'Calle Principal Barrio El Triunfo', 3161234567, 3161234567, NULL, NULL, NULL, NULL, 2.66300000, -75.52100000, 'https://images.unsplash.com/photo-1492562080023-ab3db95bfbce?w=200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1578916171728-46686eac8d58?w=1000&auto=format&fit=crop&q=80', 'activo', 1, 0, 593, '2026-09-01 10:03:36', '2026-09-01 10:26:49'),
(11, 1, 3, 4, 'Minimarket Los Ganaderos Yaguará', 'minimarket-los-ganaderos-yaguar-a-11', 'Frutas, verduras frescas de la vega, carnes frías, helados, bebidas y recargas.', 'Carrera 7 # 8-30, Barrio Upar', 3187654321, 3187654321, NULL, NULL, NULL, NULL, 2.66300000, -75.52100000, 'https://images.unsplash.com/photo-1539571696357-5a69c17a67c6?w=200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1542838132-92c53300491e?w=1000&auto=format&fit=crop&q=80', 'activo', 1, 0, 192, '2026-09-01 10:03:36', '2026-09-01 10:26:49'),
(12, 1, 3, 7, 'Tienda Mi Ranchito Sector La Playa', 'tienda-mi-ranchito-sector-la-playa-12', 'Víveres, bebidas frías, hielo en bolsa, carbón para asados y snacks para el embalse.', 'Entrada Sector La Playa', 3168901234, 3168901234, NULL, NULL, NULL, NULL, 2.66300000, -75.52100000, 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?w=200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1534723452862-4c874018d66d?w=1000&auto=format&fit=crop&q=80', 'activo', 1, 1, 581, '2026-09-01 10:03:36', '2026-09-01 10:28:57'),
(13, 1, 3, 1, 'Abarrotes & Víveres La Economía Yaguará', 'abarrotes-v-iveres-la-econom-ia-yaguar-a-13', 'Precios de mayorista en granos, aceites, azúcar, enlatados y productos de aseo.', 'Calle 4 # 1-20, Centro', 3134567890, 3134567890, NULL, NULL, NULL, NULL, 2.66300000, -75.52100000, 'https://images.unsplash.com/photo-1517841905240-472988babdf9?w=200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1583258292688-d0213dc5a3a8?w=1000&auto=format&fit=crop&q=80', 'activo', 1, 0, 202, '2026-09-01 10:03:36', '2026-09-01 10:26:49'),
(14, 1, 4, 1, 'Droguería La Principal de Yaguará', 'droguer-ia-la-principal-de-yaguar-a-14', 'Farmacia de confianza. Fórmulas médicas, inyectología certificada, toma de presión y sueros.', 'Calle 5 # 4-40, Centro', 3139871234, 3139871234, NULL, NULL, NULL, NULL, 2.66300000, -75.52100000, 'https://images.unsplash.com/photo-1559839734-2b71ea197ec2?w=200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1586015555751-63bb77f4322a?w=1000&auto=format&fit=crop&q=80', 'activo', 1, 0, 798, '2026-09-01 10:03:36', '2026-09-01 10:26:49'),
(15, 1, 4, 4, 'Farmacia San José Yaguará', 'farmacia-san-jos-e-yaguar-a-15', 'Medicamentos genéricos y de marca, pañales, leche de fórmula y artículos para bebés.', 'Carrera 6 # 9-10, Barrio Upar', 3176543210, 3176543210, NULL, NULL, NULL, NULL, 2.66300000, -75.52100000, 'https://images.unsplash.com/photo-1622253692010-333f2da6031d?w=200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1631549916768-4119b2e5f926?w=1000&auto=format&fit=crop&q=80', 'activo', 1, 1, 489, '2026-09-01 10:03:36', '2026-09-01 10:26:49'),
(16, 1, 4, 5, 'Droguería Comunitaria El Triunfo', 'droguer-ia-comunitaria-el-triunfo-16', 'Atención farmacéutica personalizada, vitaminas, analgésicos y primeros auxilios.', 'Carrera 8 # 5-15, El Triunfo', 3119876543, 3119876543, NULL, NULL, NULL, NULL, 2.66300000, -75.52100000, 'https://images.unsplash.com/photo-1594824813590-78923a1a9e88?w=200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1576602976047-174e57a47881?w=1000&auto=format&fit=crop&q=80', 'activo', 1, 0, 575, '2026-09-01 10:03:36', '2026-09-01 10:26:49'),
(17, 1, 5, 3, 'Servicios Técnicos & Motobombas Don Hernán', 'servicios-t-ecnicos-motobombas-don-hern-an-17', 'Mantenimiento preventivo y correctivo de motobombas agrícolas e instalaciones eléctricas en fincas.', 'Calle 9 # 2-45, Las Ferias', 3201239876, 3201239876, NULL, NULL, NULL, NULL, 2.66300000, -75.52100000, 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?w=200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1581092160607-ee22621dd758?w=1000&auto=format&fit=crop&q=80', 'activo', 1, 0, 604, '2026-09-01 10:03:36', '2026-09-01 10:26:49'),
(18, 1, 5, 1, 'Plomería & Redes Hidráulicas El Tigre Yaguará', 'plomer-ia-redes-hidr-aulicas-el-tigre-yaguar-a-18', 'Destape de cañerías con sonda eléctrica, tanques elevados, motobombas y griferías.', 'Carrera 2 # 4-15, Centro', 3108901234, 3108901234, NULL, NULL, NULL, NULL, 2.66300000, -75.52100000, 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1581244277943-fe4a9c777189?w=1000&auto=format&fit=crop&q=80', 'activo', 1, 1, 795, '2026-09-01 10:03:36', '2026-09-01 10:26:49'),
(19, 1, 5, 1, 'Electro-Instalaciones & Energía Solar Yaguará', 'electro-instalaciones-energ-ia-solar-yaguar-a-19', 'Instalación de paneles solares para fincas, plantas eléctricas y cableado estructurado.', 'Calle 6 # 5-30, Centro', 3147890123, 3147890123, NULL, NULL, NULL, NULL, 2.66300000, -75.52100000, 'https://images.unsplash.com/photo-1519085360753-af0119f7cbe7?w=200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1509391365360-2e959784a276?w=1000&auto=format&fit=crop&q=80', 'activo', 1, 0, 477, '2026-09-01 10:03:36', '2026-09-01 10:26:49'),
(20, 1, 6, 2, 'Cabañas Ecoturísticas & Náutica Betania View', 'caba-nas-ecotur-isticas-n-autica-betania-view-20', 'Alojamiento frente al Embalse de Betania con piscina, paseo en lancha y pesca deportiva.', 'Vía Embalse de Betania Km 3', 3149876543, 3149876543, NULL, NULL, NULL, NULL, 2.66300000, -75.52100000, 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1566073771259-6a8506099945?w=1000&auto=format&fit=crop&q=80', 'activo', 1, 0, 273, '2026-09-01 10:03:36', '2026-09-01 10:26:49'),
(21, 1, 6, 1, 'Hotel Colonial Yaguará Plaza', 'hotel-colonial-yaguar-a-plaza-21', 'Habitaciones con aire acondicionado, WiFi de alta velocidad, parqueadero y desayuno en el centro.', 'Carrera 5 # 3-25, Centro', 3116549870, 3116549870, NULL, NULL, NULL, NULL, 2.66300000, -75.52100000, 'https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?w=200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1590490360182-c33d57733427?w=1000&auto=format&fit=crop&q=80', 'activo', 1, 1, 284, '2026-09-01 10:03:36', '2026-09-01 10:26:49'),
(22, 1, 6, 8, 'Glamping & Finca Agroturística El Remanso Huilense', 'glamping-finca-agrotur-istica-el-remanso-huilense-22', 'Domo geodésico de lujo con jacuzzi privado, fogata nocturna y avistamiento de aves.', 'Vereda Upar Vía al Embalse', 3114567890, 3114567890, NULL, NULL, NULL, NULL, 2.66300000, -75.52100000, 'https://images.unsplash.com/photo-1580489944761-15a19d654956?w=200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1587061949409-02df41d5e562?w=1000&auto=format&fit=crop&q=80', 'activo', 1, 0, 309, '2026-09-01 10:03:36', '2026-09-01 10:26:49'),
